import {CATALOG} from './catalog-data.js';
export const LOCATIONS=[{id:'jacket-left',label:'Veste · intérieur gauche',detail:'Sur la doublure, au-dessus de la poche intérieure gauche.',asset:1},{id:'jacket-right',label:'Veste · intérieur droit',detail:'Sur la doublure, au-dessus de la poche intérieure droite.',asset:2},{id:'jacket-neck',label:'Veste · sous le col',detail:'À l’intérieur, au milieu du dos, juste sous le col.',asset:3},{id:'trouser-waist',label:'Pantalon · intérieur de ceinture',detail:'À l’intérieur de la ceinture, au milieu du dos.',asset:4},{id:'vest-left',label:'Gilet · intérieur gauche',detail:'Sur la doublure intérieure du gilet.',asset:5}];
export const FONT_STYLES=['italic 26px cursive','26px Georgia','italic 26px Georgia','26px Arial','italic 26px cursive','bold 26px Georgia','italic 26px Georgia','26px Arial','italic 26px cursive','small-caps 26px Georgia','italic 26px cursive','26px Arial'];
export function fontStyle(id){const n=CATALOG.groups.find(g=>g.id==='monogramFont').options.findIndex(o=>o.id===id);return FONT_STYLES[Math.max(0,n)];}
const clean=(v,max=40)=>typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,'').slice(0,max):'';
export function normalizeEmbroidery(input,legacy={}){return LOCATIONS.map((loc,i)=>{const entry=Array.isArray(input)?input.find(e=>e&&e.location===loc.id):null;const validFont=CATALOG.groups.find(g=>g.id==='monogramFont').options.some(o=>o.id===entry?.font);return {location:loc.id,enabled:entry?entry.enabled===true:!!legacy.monogramText&&i===0,text:entry&&typeof entry.text==='string'?clean(entry.text):clean(legacy.monogramText)||'Paul',font:validFont?entry.font:legacy.monogramFont||'police-1',color:/^#[0-9a-f]{6}$/i.test(entry?.color)?entry.color:'#ddc8a2'};});}
export function mountEmbroidery({getConfig,update,views}){
 const root=document.getElementById('embroidery-editor');const controls=new Map();const fonts=CATALOG.groups.find(g=>g.id==='monogramFont').options;
 for(const loc of LOCATIONS){const card=document.createElement('section');card.className='embroidery-card';const heading=document.createElement('label');heading.className='embroidery-heading';const toggle=document.createElement('input');toggle.type='checkbox';toggle.setAttribute('aria-label',`Broder à cet emplacement : ${loc.label}`);const name=document.createElement('strong');name.textContent=loc.label;heading.append(name,toggle);const desc=document.createElement('p');desc.textContent=loc.detail;
 const scene=document.createElement('div');scene.className='embroidery-scene';const img=document.createElement('img');img.src=`./assets/studio/embroidery-place-${loc.asset}.webp`;img.alt=loc.detail;img.loading='lazy';const stitch=document.createElement('span');stitch.className='embroidery-stitch';scene.append(img,stitch);
 const fields=document.createElement('div');fields.className='embroidery-fields';const text=document.createElement('input');text.type='text';text.maxLength=40;text.setAttribute('aria-label',`Inscription ${loc.label}`);text.placeholder='Paul';const font=document.createElement('select');font.setAttribute('aria-label',`Style de broderie ${loc.label}`);for(const opt of fonts){const o=document.createElement('option');o.value=opt.id;o.textContent=opt.label;font.append(o);}const color=document.createElement('input');color.type='color';color.setAttribute('aria-label',`Couleur du fil ${loc.label}`);fields.append(text,font,color);card.append(heading,desc,scene,fields);root.append(card);controls.set(loc.id,{card,toggle,text,font,color,stitch});
 function change(){const items=normalizeEmbroidery(getConfig().tailoring.embroidery,getConfig().tailoring);const index=items.findIndex(e=>e.location===loc.id);items[index]={location:loc.id,enabled:toggle.checked,text:text.value,font:font.value,color:color.value};update({tailoring:{...getConfig().tailoring,embroidery:items}});views.embroidery(loc,items[index]);}
 toggle.addEventListener('change',change);text.addEventListener('input',change);font.addEventListener('change',change);color.addEventListener('input',change);
 }
 function refresh(){const t=getConfig().tailoring;for(const entry of normalizeEmbroidery(t.embroidery,t)){const c=controls.get(entry.location);c.card.hidden=entry.location==='vest-left'&&!t.vestEnabled;c.toggle.checked=entry.enabled;c.card.classList.toggle('enabled',entry.enabled);for(const key of ['text','font','color'])if(document.activeElement!==c[key])c[key].value=entry[key];c.stitch.style.top=entry.location==='trouser-waist'?'18%':entry.location==='jacket-neck'?'42%':'45%';c.stitch.textContent=entry.text||'Paul';c.stitch.style.font=fontStyle(entry.font);c.stitch.style.color=entry.color;c.stitch.style.opacity=entry.enabled?'1':'.65';}}
 refresh();return {refresh};
}
